    fn checked(interface: Interface<'a>) -> Result<Self, Error> {
        if interface.slot_address(32).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(40).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(48).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(56).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(64).is_none() { return Err(Error::MissingSlot); }
        Ok(Self { interface })
    }
    /// Calculate real GFX9 Addr2 surface and mip geometry. Outputs unchanged on failure; scratch may change. At most64KB scratch,15mips,64MB image. No retained allocations.
    /// # Safety
    /// Caller-owned disjoint inputs, outputs and 16-byte-aligned workspace. No heap, globals, hardware I/O or retained pointers. Do not reuse workspace concurrently.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// workspace: inout, caller_owned, lifetime call, nullable=false.
    /// workspace_bytes: value, none, lifetime none, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    /// mips: output, caller_owned, lifetime call, nullable=false.
    /// mip_capacity: value, none, lifetime none, nullable=false.
