    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// coordinate: input, borrowed, lifetime call, nullable=false.
    /// workspace: inout, caller_owned, lifetime call, nullable=false.
    /// workspace_bytes: value, none, lifetime none, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#address(&self, r#request: *const R4AmdImageRequest, r#coordinate: *const R4AmdCoordinate, r#workspace: *mut u8, r#workspace_bytes: u32, r#output: *mut R4AmdImageAddress) -> i32 {
        let function: ImageV1_addressFn = unsafe { self.interface.function(40) }.expect("admitted R4L slot");
        unsafe { function(r#request, r#coordinate, r#workspace, r#workspace_bytes, r#output) }
    }
    /// Reference-only DCC/HTILE geometry from Addr2. Never enables compression or accepts unknown metadata states.
    /// # Safety
    /// Caller-owned disjoint inputs, outputs and 16-byte-aligned workspace. No heap, globals, hardware I/O or retained pointers. Do not reuse workspace concurrently.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// workspace: inout, caller_owned, lifetime call, nullable=false.
    /// workspace_bytes: value, none, lifetime none, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#metadata(&self, r#request: *const R4AmdImageRequest, r#workspace: *mut u8, r#workspace_bytes: u32, r#output: *mut R4AmdMetadata) -> i32 {
        let function: ImageV1_metadataFn = unsafe { self.interface.function(48) }.expect("admitted R4L slot");
        unsafe { function(r#request, r#workspace, r#workspace_bytes, r#output) }
    }
    /// Recompute and validate BO import. Exact modifier/topology/epoch; insufficient or misaligned backing rejected. No BO retain or mapping: owner must retain it separately.
    /// # Safety
    /// Caller-owned disjoint inputs, outputs and 16-byte-aligned workspace. No heap, globals, hardware I/O or retained pointers. Do not reuse workspace concurrently.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// request: input, borrowed, lifetime call, nullable=false.
    /// imported: input, borrowed, lifetime call, nullable=false.
