pub const render_v1_expectation: Expectation = Expectation { interface_id_lo: 0x414d4434, interface_id_hi: 0x52344f53, abi_major: 1, min_revision: 1, required_size: 56, known_required_flags: 0 };
pub const render_v1_export_name: &str = "RENDER_V1";
pub type RenderV1_shaderFn = unsafe extern "C" fn(r#profile: u32, r#code: *mut u8, r#capacity: u32, r#output: *mut R4AmdShader) -> i32;
pub type RenderV1_encode_pipelineFn = unsafe extern "C" fn(r#vertex: *const R4AmdShader, r#fragment: *const R4AmdShader, r#pipeline: *const R4AmdPipeline, r#color: *const R4AmdImageDescriptors, r#depth: *const R4AmdDepth, r#commands: *mut u32, r#capacity: u32, r#written: *mut u32) -> i32;
pub type RenderV1_encode_drawFn = unsafe extern "C" fn(r#draw: *const R4AmdDraw, r#commands: *mut u32, r#capacity: u32, r#written: *mut u32) -> i32;
/// Bounded native GFX9 shader profiles and real PM4 render encoding; active AMDGPU capabilities remain authoritative.
#[repr(C)]
#[derive(Clone, Copy)]
pub struct RenderV1 {
    pub header: InterfaceHeader,
    pub r#shader: Option<RenderV1_shaderFn>,
    pub r#encode_pipeline: Option<RenderV1_encode_pipelineFn>,
    pub r#encode_draw: Option<RenderV1_encode_drawFn>,
}
const _: () = {
    assert!(core::mem::size_of::<RenderV1>() == 56);
    assert!(core::mem::align_of::<RenderV1>() == 8);
    assert!(core::mem::offset_of!(RenderV1, r#shader) == 32);
    assert!(core::mem::offset_of!(RenderV1, r#encode_pipeline) == 40);
    assert!(core::mem::offset_of!(RenderV1, r#encode_draw) == 48);
};

pub struct RenderV1Client<'a> { interface: Interface<'a> }
impl<'a> RenderV1Client<'a> {
    pub fn init(app: &'a App<'_>) -> Result<Self, Error> {
        let interface = Interface::new(app, MODULE_NAME, render_v1_export_name, render_v1_expectation)?;
        Self::checked(interface)
    }
    pub fn optional(app: &'a App<'_>) -> Result<Option<Self>, Error> {
        Interface::optional(app, MODULE_NAME, render_v1_export_name, render_v1_expectation)?.map(Self::checked).transpose()
    }
    fn checked(interface: Interface<'a>) -> Result<Self, Error> {
        if interface.slot_address(32).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(40).is_none() { return Err(Error::MissingSlot); }
        if interface.slot_address(48).is_none() { return Err(Error::MissingSlot); }
        Ok(Self { interface })
    }
    /// Copy a fixed shader and its measured R4ACO metadata. Profiles 0 fullscreen VS/1 vertex-pull VS/2 fill PS/3 sampled PS/4 color PS/5 YUV PS. Code_address is zero until caller uploads to retained executable GPU memory. IDs0..5 are Picasso gfx902; IDs6..11 are the same six shader roles compiled separately for Raven2 gfx909.
    /// # Safety
    /// No allocation, retention, device access or submission; all buffers caller-owned and disjoint. Failure leaves outputs unchanged.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// profile: value, none, lifetime none, nullable=false.
    /// code: output, caller_owned, lifetime call, nullable=false.
    /// capacity: value, none, lifetime none, nullable=false.
    /// output: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#shader(&self, r#profile: u32, r#code: *mut u8, r#capacity: u32, r#output: *mut R4AmdShader) -> i32 {
        let function: RenderV1_shaderFn = unsafe { self.interface.function(32) }.expect("admitted R4L slot");
        unsafe { function(r#profile, r#code, r#capacity, r#output) }
    }
    /// Emit complete GFX9 pipeline and attachment state; reserve at least384 DWORDs. Color descriptors come from IMAGE_V1. Shader addresses and every attachment must remain resident until exact GPU fence retirement.
    /// # Safety
    /// No allocation, retention, device access or submission; all buffers caller-owned and disjoint. Failure leaves outputs unchanged.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// vertex: input, caller_owned, lifetime call, nullable=false.
    /// fragment: input, caller_owned, lifetime call, nullable=false.
    /// pipeline: input, caller_owned, lifetime call, nullable=false.
    /// color: input, caller_owned, lifetime call, nullable=false.
    /// depth: input, caller_owned, lifetime call, nullable=false.
    /// commands: output, caller_owned, lifetime call, nullable=false.
    /// capacity: value, none, lifetime none, nullable=false.
    /// written: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#encode_pipeline(&self, r#vertex: *const R4AmdShader, r#fragment: *const R4AmdShader, r#pipeline: *const R4AmdPipeline, r#color: *const R4AmdImageDescriptors, r#depth: *const R4AmdDepth, r#commands: *mut u32, r#capacity: u32, r#written: *mut u32) -> i32 {
        let function: RenderV1_encode_pipelineFn = unsafe { self.interface.function(40) }.expect("admitted R4L slot");
        unsafe { function(r#vertex, r#fragment, r#pipeline, r#color, r#depth, r#commands, r#capacity, r#written) }
    }
    /// Emit descriptor/push binding, viewport, clipped scissor and real DRAW_INDEX_2 or DRAW_INDEX_AUTO; reserve80 DWORDs. The preceding pipeline must use the same native shader ABI. Each complete job also requires queue cache barriers and its exact completion fence.
    /// # Safety
    /// No allocation, retention, device access or submission; all buffers caller-owned and disjoint. Failure leaves outputs unchanged.
    /// Blocking: nonblocking; threading: thread_safe; reentrancy: reentrant.
    /// draw: input, caller_owned, lifetime call, nullable=false.
    /// commands: output, caller_owned, lifetime call, nullable=false.
    /// capacity: value, none, lifetime none, nullable=false.
    /// written: output, caller_owned, lifetime call, nullable=false.
    pub unsafe fn r#encode_draw(&self, r#draw: *const R4AmdDraw, r#commands: *mut u32, r#capacity: u32, r#written: *mut u32) -> i32 {
        let function: RenderV1_encode_drawFn = unsafe { self.interface.function(48) }.expect("admitted R4L slot");
        unsafe { function(r#draw, r#commands, r#capacity, r#written) }
    }
}
